const TASKS_API_TEST_TS = [
  "// DELIVERED TaskHub test source (part of the generated slice). It is shipped as source and is NOT run by UASCO.",
  "// Covers FR4/FR6/FR9 persistence rules and FR10/FR11 board shaping against an in-memory fake of the repository.",
  "import { describe, it, expect } from 'vitest';",
  "import { TASK_STATUSES, TASK_PRIORITIES, type Task, type TaskStatus } from '../src/tasks.repo.js';",
  "",
  "// A tiny in-memory projection to exercise the board grouping rule without a live database.",
  "function groupByStatus(tasks: Task[]): Record<TaskStatus, number> {",
  "  const counts = { 'todo': 0, 'in-progress': 0, 'done': 0 } as Record<TaskStatus, number>;",
  "  for (const task of tasks) counts[task.status] += 1;",
  "  return counts;",
  "}",
  "",
  "function task(id: string, status: TaskStatus): Task {",
  "  return { id, project_id: '1', title: 'T' + id, status, priority: 'medium', due_date: null, assignee_id: null };",
  "}",
  "",
  "describe('TaskHub tasks domain', () => {",
  "  it('constrains status and priority to the allowed enums (FR6/FR7)', () => {",
  "    expect(TASK_STATUSES).toEqual(['todo', 'in-progress', 'done']);",
  "    expect(TASK_PRIORITIES).toEqual(['low', 'medium', 'high']);",
  "  });",
  "",
  "  it('places every task in exactly one status column (FR10/FR11)', () => {",
  "    const tasks = [task('1', 'todo'), task('2', 'done'), task('3', 'done')];",
  "    const counts = groupByStatus(tasks);",
  "    expect(counts).toEqual({ 'todo': 1, 'in-progress': 0, 'done': 2 });",
  "    const total = counts['todo'] + counts['in-progress'] + counts['done'];",
  "    expect(total).toBe(tasks.length);",
  "  });",
  "});",
  ""
].join("\n");

